WITH candidates AS MATERIALIZED ( SELECT asset.id AS id, date(asset.created_at) AS day, asset.filename AS sort_value FROM asset WHERE asset.repository_id = ? AND asset.is_recycled = ? AND asset.is_pipeline_processed = ? AND asset.created_at IS NOT NULL AND date(asset.created_at) <= ? AND (date(asset.created_at) < ? OR (asset.filename > ? OR (asset.filename = ? AND asset.id > ?))) ORDER BY date(asset.created_at) DESC, +asset.filename ASC, asset.id ASC LIMIT 51 ), page AS MATERIALIZED ( SELECT id, day, sort_value FROM candidates ORDER BY day DESC, sort_value ASC, id ASC LIMIT 50 ), day_counts AS MATERIALIZED ( SELECT p.day AS day, (SELECT count(*) FROM (SELECT asset.id FROM asset WHERE asset.repository_id = ? AND asset.is_recycled = ? AND asset.is_pipeline_processed = ? AND asset.created_at IS NOT NULL AND date(asset.created_at) = p.day ) AS m) AS n FROM (SELECT DISTINCT day FROM page) AS p ) SELECT asset.*, p.day AS day, p.sort_value AS sort_value, d.n AS day_total, (SELECT count(*) FROM candidates) AS candidate_count FROM page AS p JOIN asset ON asset.id = p.id LEFT JOIN day_counts AS d ON d.day = p.day ORDER BY p.day DESC, p.sort_value ASC, p.id ASC